        { text: "كان رسول الله ﷺ يكثر أن يقول: يا مقلّب القلوب ثبّت قلبي على دينك", source: "الترمذي (2140)، وصححه الألباني" },
        { text: "ألا سألوا إذ لم يعلموا، فإنما شفاء العِيّ السؤال", source: "أبو داود (336)، وحسّنه الألباني" }
